    const roleChangeAudit=await db.collection("tenant_audit_events").findOne({tenantId:secondCompanyInternalId,actorId:"test-user",action:"member.role_changed",resourceType:"membership",resourceId:"test-user-beta","metadata.previousRole":"member","metadata.newRole":"manager"});
